def transform(grid):
    h, w = len(grid), len(grid[0])

    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest contiguous non-background line, horizontal or vertical.
    best = None
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            run = (c - start, "h", r, start)
            if best is None or run[0] > best[0]:
                best = run

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            run = (r - start, "v", start, c)
            if best is None or run[0] > best[0]:
                best = run

    length, direction, r0, c0 = best
    if direction == "h":
        motif = grid[r0][c0:c0 + length]
    else:
        motif = [grid[r0 + i][c0] for i in range(length)]

    motif_cells = set()
    for i in range(length):
        motif_cells.add((r0, c0 + i) if direction == "h" else (r0 + i, c0))

    outside = Counter(
        grid[r][c]
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg and (r, c) not in motif_cells
    )
    marker = outside.most_common(1)[0][0]

    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker]
    anchor = length // 2

    for r, c in markers:
        for i, value in enumerate(motif):
            offset = i - anchor
            rr, cc = (r, c + offset) if direction == "h" else (r + offset, c)
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value

    return out
